/** Adjacency connection lines between covered districts */
const CONNECTIONS: [string, string][] = [
  ["sabarkantha", "mehsana"],
  ["mehsana", "gandhinagar"],
  ["gandhinagar", "ahmedabad"],
  ["gandhinagar", "kheda"],
  ["ahmedabad", "kheda"],
];

interface GujaratMapProps {
  hoveredDistrict: string | null;
  onHoverDistrict: (district: string | null) => void;
}

export const GujaratMap: FC<GujaratMapProps> = ({ hoveredDistrict, onHoverDistrict }) => {
  const findDistrict = (id: string) => COVERED_DISTRICTS.find((d) => d.id === id)!;

  return (
    <div className="relative mx-auto w-full max-w-[560px] lg:ml-auto lg:mr-0">
      <svg
        viewBox="0 0 600 520"
        className="w-full h-auto drop-shadow-2xl"
        role="img"
        aria-label="Map of Gujarat state highlighting 5 coverage districts: Ahmedabad, Gandhinagar, Kheda, Mehsana, Sabarkantha"
      >
        <defs>
          <filter id="district-glow" x="-30%" y="-30%" width="160%" height="160%">
            <feGaussianBlur stdDeviation="6" result="blur" />
            <feMerge>
              <feMergeNode in="blur" />
              <feMergeNode in="SourceGraphic" />
            </feMerge>
          </filter>
          <linearGradient id="gold-active" x1="0%" y1="0%" x2="100%" y2="100%">
            <stop offset="0%" stopColor="#F5D76E" />
            <stop offset="100%" stopColor="#C9A227" />
          </linearGradient>
          <radialGradient id="dot-glow" cx="50%" cy="50%" r="50%">
            <stop offset="0%" stopColor="#C9A227" stopOpacity="0.6" />
            <stop offset="100%" stopColor="#C9A227" stopOpacity="0" />
          </radialGradient>
        </defs>

        {/* Base layer: All non-covered districts of Gujarat */}
        <g className="opacity-40 hover:opacity-60 transition-opacity duration-300">
          {OTHER_DISTRICTS.map((d) => (
            <path
              key={d.id}
              d={d.path}
              fill="rgba(255,255,255,0.06)"
              stroke="rgba(255,255,255,0.25)"
              strokeWidth="0.8"
              strokeLinejoin="round"
              className="transition-all duration-300 hover:fill-[rgba(255,255,255,0.15)]"
            >
              <title>{d.name}</title>
            </path>
          ))}
        </g>

        {/* Connection network between covered districts */}
        {CONNECTIONS.map(([a, b]) => {
          const da = findDistrict(a);
          const db = findDistrict(b);
          const active = hoveredDistrict === a || hoveredDistrict === b;
          return (
            <line
              key={`${a}-${b}`}
              x1={da.cx}
              y1={da.cy}
              x2={db.cx}
              y2={db.cy}
              stroke={active ? "rgba(245,215,110,0.9)" : "rgba(201,162,39,0.35)"}
              strokeWidth={active ? 2 : 1}
              strokeDasharray={active ? "none" : "3 3"}
              className="transition-all duration-300"
            />
          );
        })}

        {/* Layer 1: Covered Districts polygon shapes */}
        {COVERED_DISTRICTS.map((d, i) => {
          const active = hoveredDistrict === d.id;
          return (
            <path
              key={d.id}
              d={d.path}
              fill={active ? "url(#gold-active)" : "rgba(201,162,39,0.35)"}
              stroke={active ? "#FFFFFF" : "rgba(245,215,110,0.85)"}
              strokeWidth={active ? 2.5 : 1.2}
              strokeLinejoin="round"
              filter={active ? "url(#district-glow)" : undefined}
              onMouseEnter={() => onHoverDistrict(d.id)}
              onMouseLeave={() => onHoverDistrict(null)}
              className="cursor-pointer transition-all duration-300 map-district-enter"
              style={{ animationDelay: `${i * 100 + 200}ms` }}
            />
          );
        })}

        {/* Layer 2: District dots and map labels */}
        {COVERED_DISTRICTS.map((d, i) => {
          const active = hoveredDistrict === d.id;
          return (
            <g
              key={d.id}
              onMouseEnter={() => onHoverDistrict(d.id)}
              onMouseLeave={() => onHoverDistrict(null)}
              className="cursor-pointer pointer-events-auto"
            >
              {/* Pulsing glow ring around location dot */}
              <circle
                cx={d.cx}
                cy={d.cy}
                r={active ? 22 : 14}
                fill="url(#dot-glow)"
                className={`transition-all duration-500 map-dot-enter ${active ? "map-dot-pulse" : ""}`}
                style={{ animationDelay: `${i * 100 + 400}ms` }}
              />

              {/* Central location marker pin dot */}
              <circle
                cx={d.cx}
                cy={d.cy}
                r={active ? 5.5 : 4}
                fill="#F5D76E"
                stroke={active ? "#0B1F3A" : "rgba(11,31,58,0.7)"}
                strokeWidth={1.5}
                className="transition-all duration-300 map-dot-enter"
                style={{ animationDelay: `${i * 100 + 400}ms` }}
              />

              {/* District Name Label directly on map */}
              <text
                x={d.cx}
                y={d.cy + (active ? 22 : 17)}
                textAnchor="middle"
                fill={active ? "#FFFFFF" : "rgba(255,255,255,0.95)"}
                fontSize={active ? "12" : "10.5"}
                fontWeight="700"
                fontFamily="Poppins, Inter, sans-serif"
                className="pointer-events-none transition-all duration-300 select-none drop-shadow-[0_1px_3px_rgba(0,0,0,0.9)]"
              >
                {d.name}
              </text>
            </g>
          );
        })}

        {/* Layer 3: Active Hover Tooltip Popup - ALWAYS ON VERY TOP */}
        {(() => {
          const activeItem = COVERED_DISTRICTS.find((d) => d.id === hoveredDistrict);
          if (!activeItem) return null;
          return (
            <g className="pointer-events-none map-tooltip-enter">
              <rect
                x={activeItem.cx - 80}
                y={activeItem.cy - 58}
                width={160}
                height={44}
                rx={8}
                fill="#0B1F3A"
                stroke="#F5D76E"
                strokeWidth={1.5}
                className="drop-shadow-[0_8px_16px_rgba(0,0,0,0.6)]"
              />
              <polygon
                points={`${activeItem.cx - 6},${activeItem.cy - 14} ${activeItem.cx + 6},${activeItem.cy - 14} ${activeItem.cx},${activeItem.cy - 7}`}
                fill="#F5D76E"
              />
              <text
                x={activeItem.cx}
                y={activeItem.cy - 38}
                textAnchor="middle"
                fill="#F5D76E"
                fontSize="12"
                fontWeight="700"
                fontFamily="Poppins, Inter, sans-serif"
              >
                {activeItem.name}
              </text>
              <text
                x={activeItem.cx}
                y={activeItem.cy - 22}
                textAnchor="middle"
                fill="rgba(255,255,255,0.9)"
                fontSize="9.5"
                fontWeight="500"
                fontFamily="Inter, sans-serif"
              >
                {activeItem.role}
              </text>
            </g>
          );
        })()}
      </svg>

      {/* Legend Badge */}
      <div className="mt-3 flex items-center justify-center gap-6 text-xs text-primary-foreground/80 font-medium">
        <div className="flex items-center gap-2 bg-primary-foreground/5 border border-primary-foreground/10 px-3 py-1.5 rounded-full">
          <span className="size-3 rounded-full bg-accent inline-block shadow-[0_0_8px_rgba(201,162,39,0.8)]" />
          <span>Covered Districts (5)</span>
        </div>
        <div className="flex items-center gap-2 bg-primary-foreground/5 border border-primary-foreground/10 px-3 py-1.5 rounded-full">
          <span className="size-3 rounded-full bg-white/20 inline-block" />
          <span>Other Gujarat State Regions</span>
        </div>
      </div>
    </div>
  );
};
